      flex-wrap: wrap;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-header h2 {
      font-size: clamp(1.5rem, 2vw, 2rem);
      letter-spacing: -0.02em;
    }

    .section-lede {
      max-width: 50ch;
    }

    .card-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card,
    .deal-card,
    .story-card {
      min-width: 0;
      border-radius: var(--radius-lg);
      border: 1px solid #ffffff12;
      background: linear-gradient(180deg, #ffffff08 0%, #ffffff04 100%);
      overflow: hidden;
    }

    .product-card {
      display: grid;
      grid-template-rows: auto 1fr;
    }

    .card-visual {
      min-height: 14rem;
      border-bottom: 1px solid #ffffff10;
      position: relative;
      overflow: hidden;
      background: linear-gradient(160deg, #10192b 0%, #1b2740 100%);
    }

    .card-visual::before,
    .card-visual::after {
      content: "";
      position: absolute;
      border-radius: 50%;
      filter: blur(0.5rem);
    }

    .card-visual::before {
      inset: 18% auto auto 18%;
      width: 7rem;
      height: 7rem;
      background: linear-gradient(135deg, #32d5c8, #7d72ff);
    }

    .card-visual::after {
      inset: auto 16% 12% auto;
      width: 5rem;
      height: 5rem;
      background: linear-gradient(135deg, #ffb55f, #ff7b7b);
    }

    .card-badge {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.35rem 0.7rem;
      border-radius: 999px;
      background: #09101de6;
      border: 1px solid #ffffff18;
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .card-copy {
      display: grid;
      gap: 0.9rem;
      padding: 1rem;
      min-width: 0;
    }

    .card-copy h3,
    .deal-copy h3,
    .story-copy h3 {
      font-size: 1.15rem;
      letter-spacing: -0.02em;
    }

    .meta-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
      align-items: center;
      justify-content: space-between;
    }

    .price {
      font-size: 1.35rem;
      font-weight: 800;
      color: var(--text);
    }

    .badge {
      display: inline-flex;
      align-items: center;
      min-height: 1.9rem;
      padding: 0.3rem 0.6rem;
      border-radius: 999px;
      background: #ffffff08;
      border: 1px solid #ffffff12;
      color: var(--muted);
      font-size: 0.82rem;
      font-weight: 600;
    }

    .card-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 0.45rem;
    }

    .card-tags li {
      padding: 0.35rem 0.55rem;
      border-radius: 999px;
      background: #ffffff07;
      border: 1px solid #ffffff10;
      color: var(--muted);
      font-size: 0.8rem;
    }

    .card-link,
    .text-link {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      width: fit-content;
      font-weight: 700;
      color: var(--accent-2);
    }

    .card-link::after,
    .text-link::after {
      content: "→";
      transition: transform 180ms ease;
    }

    .card-link:hover::after,
    .card-link:focus-visible::after,
    .text-link:hover::after,
    .text-link:focus-visible::after {
      transform: translateX(2px);
    }

    .deal-card {
      padding: 1rem;
      display: grid;
      gap: 0.9rem;
    }

    .deal-banner {
      display: grid;
      gap: 0.3rem;
      padding: 1rem;
      border-radius: var(--radius-md);
      background:
        linear-gradient(135deg, #7d72ff1f, #32d5c81a),
        #ffffff05;
      border: 1px solid #ffffff12;
    }

    .deal-banner strong {
      font-size: 1rem;
    }

    .deal-banner span {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .deal-points li {
      display: flex;
      gap: 0.55rem;
      align-items: flex-start;
      color: var(--muted);
    }

    .deal-points li::before {
      content: "";
      flex: none;
      width: 0.65rem;
      height: 0.65rem;
      margin-top: 0.4rem;
      border-radius: 50%;
      background: var(--accent-3);
      box-shadow: 0 0 0 4px #ffb55f1f;
    }

    .story-card {
      display: grid;
      gap: 1rem;
      padding: 1rem;
    }

    .story-visual {
      min-height: 11rem;
      border-radius: calc(var(--radius-lg) - 6px);
      background:
        linear-gradient(135deg, #172136 0%, #111b2b 100%);
      border: 1px solid #ffffff10;
      position: relative;
      overflow: hidden;
    }

    .story-visual::before,
    .story-visual::after {
      content: "";
      position: absolute;
      border-radius: 24px;
      background: linear-gradient(135deg, #32d5c8, #7d72ff);
