      line-height: 1.5;
      text-rendering: optimizeLegibility;
    }

    img {
      max-width: 100%;
      display: block;
    }

    a {
      color: inherit;
    }

    a, button {
      -webkit-tap-highlight-color: transparent;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-160%);
      z-index: 1000;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--accent-2);
      color: #031312;
      font-weight: 700;
      text-decoration: none;
      transition: transform 180ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page {
      width: min(100%, var(--content-width));
      margin: 0 auto;
      padding: 1rem 1rem 4rem;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 10;
      backdrop-filter: blur(18px);
      background: linear-gradient(180deg, #08101fea 0%, #08101fb8 100%);
      border-bottom: 1px solid #ffffff12;
    }

    .site-header-inner,
    .site-footer-inner {
      width: min(100%, var(--content-width));
      margin: 0 auto;
      padding: 1rem;
    }

    .site-header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      text-decoration: none;
      font-weight: 800;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .brand-mark {
      width: 2.25rem;
      height: 2.25rem;
      border-radius: 50%;
      background:
        radial-gradient(circle at 30% 30%, #ffffff 0 10%, transparent 11%),
        conic-gradient(from 215deg, var(--accent-2), var(--accent), var(--accent-3), var(--accent-2));
      box-shadow: 0 10px 24px #00000066;
    }

    .brand small {
      display: block;
      color: var(--muted);
      font-size: 0.72rem;
      letter-spacing: 0.12em;
      text-transform: none;
      font-weight: 600;
    }

    .primary-nav ul,
    .trust-list,
    .quick-stats,
    .deal-points,
    .category-list,
    .card-tags,
    .footer-links {
      list-style: none;
      margin: 0;
      padding: 0;
    }

    .primary-nav ul {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      justify-content: flex-end;
    }

    .nav-link,
    .pill-link,
    .text-link,
    .card-link {
      text-decoration: none;
    }

    .nav-link {
      display: inline-flex;
      align-items: center;
      min-height: 2.5rem;
      padding: 0.55rem 0.9rem;
      border-radius: 999px;
      color: var(--muted);
      border: 1px solid transparent;
    }

    .nav-link:hover,
    .nav-link:focus-visible {
      color: var(--text);
      border-color: var(--line-strong);
      background: #ffffff08;
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1.3fr) minmax(280px, 0.9fr);
      gap: 1.25rem;
      align-items: stretch;
      margin-top: 1.25rem;
    }

    .panel {
      border: 1px solid #ffffff12;
      border-radius: var(--radius-xl);
      background:
        linear-gradient(180deg, #ffffff0a 0%, #ffffff05 100%),
        linear-gradient(180deg, var(--surface), var(--surface-2));
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.25rem, 2vw, 2rem);
      display: grid;
      gap: 1.25rem;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      width: fit-content;
      padding: 0.42rem 0.8rem;
      border-radius: 999px;
      background: #ffffff0a;
      border: 1px solid #ffffff12;
      color: var(--muted);
      font-size: 0.86rem;
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 0.6rem;
      height: 0.6rem;
      border-radius: 50%;
      background: var(--accent-2);
      box-shadow: 0 0 0 4px #32d5c826;
    }

    h1, h2, h3, p {
      margin: 0;
    }

    h1 {
      font-size: clamp(2.5rem, 7vw, 5.4rem);
      line-height: 0.95;
      letter-spacing: -0.04em;
      max-width: 10ch;
    }

    .hero-copy p,
    .section-lede,
    .card-copy p,
    .deal-copy p,
    .story-copy p,
    .hero-note,
    .meta {
      color: var(--muted);
    }

    .hero-copy p {
      max-width: 58ch;
      font-size: 1.08rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
    }

    .button,
    .button-secondary {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 3rem;
      padding: 0.8rem 1.15rem;
      border-radius: 999px;
      font-weight: 700;
      text-decoration: none;
      border: 1px solid transparent;
    }

    .button {
      background: linear-gradient(135deg, var(--accent-2), #77f2e8);
      color: #031312;
      box-shadow: 0 14px 36px #32d5c833;
    }

    .button-secondary {
      background: #ffffff08;
      border-color: var(--line);
      color: var(--text);
    }

    .button:hover,
    .button-secondary:hover,
    .button:focus-visible,
    .button-secondary:focus-visible,
    .text-link:hover,
    .text-link:focus-visible,
    .card-link:hover,
    .card-link:focus-visible,
    .pill-link:hover,
    .pill-link:focus-visible {
      transform: translateY(-1px);
    }

    .quick-stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.75rem;
    }

    .stat {
      padding: 0.95rem;
      border-radius: var(--radius-md);
      background: #0a1220;
      border: 1px solid #ffffff0f;
    }

    .stat strong {
      display: block;
      font-size: 1.15rem;
      margin-bottom: 0.2rem;
    }

    .stat span {
      color: var(--muted-2);
      font-size: 0.92rem;
    }

    .hero-spotlight {
      display: grid;
      gap: 1rem;
      padding: clamp(1.1rem, 2vw, 1.5rem);
    }

    .spotlight-visual {
      min-height: 16rem;
      border-radius: calc(var(--radius-xl) - 8px);
      border: 1px solid #ffffff12;
      background:
        radial-gradient(circle at 20% 30%, #32d5c833 0 18%, transparent 19%),
        radial-gradient(circle at 75% 25%, #7d72ff33 0 16%, transparent 17%),
        radial-gradient(circle at 60% 78%, #ffb55f26 0 18%, transparent 19%),
        linear-gradient(145deg, #0f1830 0%, #17233c 44%, #111826 100%);
      position: relative;
      overflow: hidden;
    }

    .spotlight-visual::after {
      content: "";
      position: absolute;
      inset: auto 10% 14% 10%;
      height: 3.5rem;
      border-radius: 999px;
      background: linear-gradient(90deg, #ffffff10, #ffffff28, #ffffff10);
      filter: blur(0.4rem);
    }

    .spotlight-content {
      display: grid;
      gap: 0.5rem;
    }

    .spotlight-content h2 {
      font-size: 1.35rem;
    }

    .spotlight-content .meta {
      font-size: 0.94rem;
    }

    .category-list {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
    }

    .pill-link {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      min-height: 2.35rem;
      padding: 0.45rem 0.8rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      color: var(--text);
      background: #ffffff06;
    }

    .section {
      margin-top: 1.25rem;
      padding: clamp(1.15rem, 2vw, 1.6rem);
    }

    .section-header {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-header h2 {
      font-size: clamp(1.5rem, 2vw, 2rem);
      letter-spacing: -0.02em;
    }

    .section-lede {
      max-width: 50ch;
    }

    .card-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card,
    .deal-card,
    .story-card {
      min-width: 0;
      border-radius: var(--radius-lg);
      border: 1px solid #ffffff12;
      background: linear-gradient(180deg, #ffffff08 0%, #ffffff04 100%);
      overflow: hidden;
    }

    .product-card {
      display: grid;
      grid-template-rows: auto 1fr;
    }

    .card-visual {
      min-height: 14rem;
      border-bottom: 1px solid #ffffff10;
      position: relative;
      overflow: hidden;
      background: linear-gradient(160deg, #10192b 0%, #1b2740 100%);
    }

    .card-visual::before,
    .card-visual::after {
      content: "";
      position: absolute;
      border-radius: 50%;
      filter: blur(0.5rem);
    }

    .card-visual::before {
      inset: 18% auto auto 18%;
      width: 7rem;
      height: 7rem;
      background: linear-gradient(135deg, #32d5c8, #7d72ff);
    }

    .card-visual::after {
      inset: auto 16% 12% auto;
      width: 5rem;
      height: 5rem;
      background: linear-gradient(135deg, #ffb55f, #ff7b7b);
    }

    .card-badge {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.35rem 0.7rem;
      border-radius: 999px;
      background: #09101de6;
      border: 1px solid #ffffff18;
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .card-copy {
      display: grid;
      gap: 0.9rem;
      padding: 1rem;
      min-width: 0;
    }

    .card-copy h3,
    .deal-copy h3,
    .story-copy h3 {
      font-size: 1.15rem;
      letter-spacing: -0.02em;
    }

    .meta-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
      align-items: center;
      justify-content: space-between;
    }

    .price {
      font-size: 1.35rem;
      font-weight: 800;
      color: var(--text);
    }

    .badge {
      display: inline-flex;
      align-items: center;
      min-height: 1.9rem;
      padding: 0.3rem 0.6rem;
      border-radius: 999px;
      background: #ffffff08;
      border: 1px solid #ffffff12;
      color: var(--muted);
      font-size: 0.82rem;
      font-weight: 600;
    }

    .card-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 0.45rem;
    }

    .card-tags li {
      padding: 0.35rem 0.55rem;
      border-radius: 999px;
      background: #ffffff07;
      border: 1px solid #ffffff10;
      color: var(--muted);
      font-size: 0.8rem;
    }

    .card-link,
    .text-link {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      width: fit-content;
      font-weight: 700;
      color: var(--accent-2);
    }

    .card-link::after,
    .text-link::after {
      content: "→";
      transition: transform 180ms ease;
    }

    .card-link:hover::after,
    .card-link:focus-visible::after,
    .text-link:hover::after,
    .text-link:focus-visible::after {
      transform: translateX(2px);
    }

    .deal-card {
      padding: 1rem;
      display: grid;
      gap: 0.9rem;
    }

    .deal-banner {
      display: grid;
      gap: 0.3rem;
      padding: 1rem;
      border-radius: var(--radius-md);
      background:
        linear-gradient(135deg, #7d72ff1f, #32d5c81a),
        #ffffff05;
      border: 1px solid #ffffff12;
    }

    .deal-banner strong {
      font-size: 1rem;
    }

    .deal-banner span {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .deal-points li {
      display: flex;
      gap: 0.55rem;
      align-items: flex-start;
      color: var(--muted);
    }

    .deal-points li::before {
      content: "";
      flex: none;
      width: 0.65rem;
      height: 0.65rem;
      margin-top: 0.4rem;
      border-radius: 50%;
      background: var(--accent-3);
      box-shadow: 0 0 0 4px #ffb55f1f;
    }

    .story-card {
      display: grid;
      gap: 1rem;
      padding: 1rem;
    }

    .story-visual {
      min-height: 11rem;
      border-radius: calc(var(--radius-lg) - 6px);
      background:
        linear-gradient(135deg, #172136 0%, #111b2b 100%);
      border: 1px solid #ffffff10;
      position: relative;
      overflow: hidden;
    }

    .story-visual::before,
    .story-visual::after {
      content: "";
      position: absolute;
      border-radius: 24px;
      background: linear-gradient(135deg, #32d5c8, #7d72ff);
    }

    .story-visual::before {
      inset: 18% 18% auto auto;
      width: 42%;
      height: 56%;
      transform: rotate(10deg);
    }

    .story-visual::after {
      inset: auto auto 14% 12%;
      width: 55%;
      height: 16%;
      background: linear-gradient(90deg, #ffb55f, #ff7b7b);
    }

    .story-copy {
      display: grid;
      gap: 0.7rem;
    }

    .story-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      color: var(--muted-2);
      font-size: 0.9rem;
    }

    .story-meta span + span::before {
      content: "•";
      margin-right: 0.5rem;
      color: var(--muted-2);
    }

    .site-footer {
      margin-top: 1.25rem;
      border-top: 1px solid #ffffff10;
      background: linear-gradient(180deg, #08101f00, #08101f88);
    }

    .site-footer-inner {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
    }

    .footer-links a {
      color: var(--muted);
      text-decoration: none;
    }

    .footer-links a:hover,
    .footer-links a:focus-visible {
      color: var(--text);
    }

    .footer-note {
      color: var(--muted-2);
      font-size: 0.92rem;
    }

    :focus-visible {
      outline: 2px solid var(--focus);
      outline-offset: 3px;
    }

    @media (max-width: 920px) {
      .hero,
      .card-grid {
        grid-template-columns: 1fr;
      }

      .site-header-inner,
      .site-footer-inner {
        align-items: flex-start;
      }
    }

    @media (max-width: 720px) {
      .site-header-inner {
        flex-direction: column;
      }

      .primary-nav ul {
        justify-content: flex-start;
      }

      .quick-stats {
        grid-template-columns: 1fr;
      }

      .page {
        padding-inline: 0.75rem;
      }
    }

    @media (forced-colors: active) {
      * {
        forced-color-adjust: auto;
      }

      body,
      .site-header,
      .panel,
      .product-card,
      .deal-card,
      .story-card,
      .stat,
      .pill-link,
      .button-secondary,
      .nav-link {
        background: Canvas;
        color: CanvasText;
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .button,
      .skip-link,
      .badge,
      .card-badge,
      .eyebrow {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonBorder;
      }

      :focus-visible {
        outline-color: Highlight;
      }

      .card-link,
      .text-link {
        color: LinkText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>
  <div id="app"></div>

  <script>
    const featuredProducts = [
      {
        badge: "New season",
        category: "Outerwear",
        title: "Solstice Shell Jacket",
        description: "A weather-ready layer with a matte finish, sealed seams, and a relaxed silhouette for city commutes.",
        price: "$188",
        tags: ["Waterproof", "Breathable", "Unisex"],
        href: "#featured"
      },
      {
        badge: "Best seller",
        category: "Footwear",
        title: "Atlas Runner",
        description: "Soft rebound foam and a stable tread keep this everyday sneaker comfortable from errands to evenings out.",
        price: "$142",
        tags: ["Lightweight", "All-day comfort", "Recycled lining"],
        href: "#featured"
      },
      {
        badge: "Limited",
        category: "Accessories",
        title: "Luna Carry Tote",
        description: "Structured enough for workdays, streamlined enough for weekends, and sized for the pieces you use most.",
        price: "$96",
        tags: ["Everyday carry", "Internal pocket", "Magnetic closure"],
        href: "#featured"
      }
    ];

    const dealItems = [
      "Bundle select layers and save 20% at checkout.",
      "Free shipping on orders over $75, every day this week.",
      "Members get early access to tomorrow's drop at 8 a.m."
    ];

    const editorialStories = [
      {
        category: "Style guide",
        title: "Three ways to build a wardrobe that works across seasons.",
        description: "Our editors map out a simple formula for mixing outerwear, knitwear, and accessories without overbuying.",
        meta: "6 min read",
        href: "#journal"
      },
      {
        category: "Behind the scenes",
        title: "How we source durable materials with a lower footprint.",
        description: "From recycled yarns to water-conscious finishing, learn what goes into the products we spotlight.",
        meta: "4 min read",
        href: "#journal"
      },
      {
        category: "Gift edit",
        title: "Small upgrades that make a big difference for daily routines.",
        description: "A concise pick list of useful objects that feel considered, personal, and ready to wrap.",
        meta: "5 min read",
        href: "#journal"
      }
    ];

    const categories = ["Women's", "Men's", "Home", "Beauty", "Gifts"];

    function escapeHtml(value) {
      return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function sectionHeader(eyebrow, titleId, title, description, linkLabel, href) {
      return `
        <div class="section-header">
          <div>
            <p class="eyebrow">${escapeHtml(eyebrow)}</p>
            <h2 id="${escapeHtml(titleId)}">${escapeHtml(title)}</h2>
          </div>
          <p class="section-lede">${escapeHtml(description)}</p>
          ${linkLabel ? `<a class="text-link" href="${escapeHtml(href)}">${escapeHtml(linkLabel)}</a>` : ""}
        </div>
      `;
    }

    function productCard(product) {
      return `
        <article class="product-card">
          <div class="card-visual" aria-hidden="true">
            <span class="card-badge">${escapeHtml(product.badge)}</span>
          </div>
          <div class="card-copy">
            <div class="meta-row">
              <span class="badge">${escapeHtml(product.category)}</span>
              <span class="price">${escapeHtml(product.price)}</span>
            </div>
            <div>
              <h3>${escapeHtml(product.title)}</h3>
              <p>${escapeHtml(product.description)}</p>
            </div>
            <ul class="card-tags">
              ${product.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join("")}
            </ul>
            <a class="card-link" href="${escapeHtml(product.href)}">View ${escapeHtml(product.title)}</a>
          </div>
        </article>
      `;
    }

    function dealCard() {
      return `
        <article class="deal-card">
          <div class="deal-banner">
            <strong>Seasonal savings, curated for easy shopping</strong>
            <span>Valid on selected collections while inventory lasts.</span>
          </div>
          <h3>Today’s top deal</h3>
          <ul class="deal-points">
            ${dealItems.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}
          </ul>
          <a class="button" href="#featured">Shop featured savings</a>
        </article>
      `;
    }

    function editorialCard(story) {
      return `
        <article class="story-card">
          <div class="story-visual" aria-hidden="true"></div>
          <div class="story-copy">
            <div class="story-meta">
              <span>${escapeHtml(story.category)}</span>
              <span>${escapeHtml(story.meta)}</span>
            </div>
            <h3>${escapeHtml(story.title)}</h3>
            <p>${escapeHtml(story.description)}</p>
            <a class="card-link" href="${escapeHtml(story.href)}">Read the story</a>
          </div>
        </article>
      `;
    }

    function hero() {
      return `
        <section class="hero" aria-labelledby="hero-title">
          <div class="panel hero-copy">
            <p class="eyebrow">Retail drop • New arrivals live now</p>
            <h1 id="hero-title">Modern essentials for a darker, sharper everyday.</h1>
            <p>
              Discover a retail edit that balances premium materials, versatile silhouettes, and editorial styling.
              Built for quick browsing, effortless gifting, and the kind of pieces that keep earning their place.
            </p>
            <div class="hero-actions">
              <a class="button" href="#featured">Explore featured products</a>
              <a class="button-secondary" href="#deals">See today's deals</a>
            </div>
            <ul class="quick-stats" aria-label="Store highlights">
              <li class="stat">
                <strong>48-hour dispatch</strong>
                <span>Fast packing for in-stock orders.</span>
              </li>
              <li class="stat">
                <strong>30-day returns</strong>
                <span>Easy exchanges if the fit is off.</span>
              </li>
              <li class="stat">
                <strong>Member perks</strong>
                <span>Early access, curated drops, and saves.</span>
              </li>
            </ul>
          </div>

          <aside class="panel hero-spotlight" aria-label="Spotlight collection">
            <div class="spotlight-visual" aria-hidden="true"></div>
            <div class="spotlight-content">
              <p class="eyebrow">Spotlight collection</p>
              <h2>Cold-weather layers with a clean, minimal finish.</h2>
              <p class="meta">
                Limited-run textures, darker palettes, and easy-to-style silhouettes designed to anchor the season.
              </p>
              <ul class="category-list" aria-label="Browse popular categories">
                ${categories.map((item) => `<li><a class="pill-link" href="#featured">${escapeHtml(item)}</a></li>`).join("")}
              </ul>
            </div>
          </aside>
        </section>
      `;
    }

    function app() {
      return `
        <header class="site-header">
          <div class="site-header-inner">
            <a class="brand" href="#" aria-label="Nocturne Market home">
              <span class="brand-mark" aria-hidden="true"></span>
              <span>
